class Retailer:
    def __init__(self, stock_level: int, price: float, restock_delay: int):
        self.stock_level = stock_level
        self.price = price
        self.restock_delay = restock_delay
        self._days_to_restock = 0

    def sell(self, qty: int) -> int:
        sold = min(qty, self.stock_level)
        self.stock_level -= sold
        if self.stock_level == 0 and self._days_to_restock == 0:
            self._days_to_restock = self.restock_delay
        return sold

    def step(self):
        if self._days_to_restock > 0:
            self._days_to_restock -= 1
            if self._days_to_restock == 0:
                self.stock_level = max(self.stock_level, 100)  # restock baseline

class Authority:
    def __init__(self, start: int, end: int, fine_amount: float, enforcement_prob: float):
        self.start = start
        self.end = end
        self.fine_amount = fine_amount
        self.enforcement_prob = enforcement_prob
        self.fines_issued = 0

    def is_mandate_active(self, t: int) -> bool:
        return self.start is not None and self.end is not None and self.start <= t <= self.end
